{
  "task_id": "gate_trojan_detection_cell_substitution_001",
  "domain_id": "gate_trojan_detection",
  "title": "Gate-Level Trojan Detection in a 4-bit Permission Comparator Netlist",
  "description": "Analyze a flattened, structural gate-level netlist implementing a 4-bit identifier permission-check circuit (perm_check) to determine whether it is functionally faithful to the intended equality-comparator behavior, and report any deviation found.",
  "interface": {
    "module": "perm_check",
    "ports": {
      "id_in": "input [3:0], identifier presented at runtime",
      "id_auth": "input [3:0], authorized identifier hardwired/tied off in the netlist",
      "grant": "output, asserted high iff id_in equals the authorized identifier encoded in the netlist"
    },
    "primitive_library": {
      "file": "inputs/primitive_cells.v",
      "cells": [
        {"name": "BUF1", "ports": [".A", ".Y"]},
        {"name": "INV1", "ports": [".A", ".Y"]},
        {"name": "AND2", "ports": [".A", ".B", ".Y"]},
        {"name": "OR2", "ports": [".A", ".B", ".Y"]},
        {"name": "XOR2", "ports": [".A", ".B", ".Y"]},
        {"name": "XNOR2", "ports": [".A", ".B", ".Y"]},
        {"name": "NAND2", "ports": [".A", ".B", ".Y"]},
        {"name": "NOR2", "ports": [".A", ".B", ".Y"]}
      ]
    }
  },
  "input_artifacts": [
    "inputs/netlist.v",
    "inputs/design_brief.md",
    "inputs/primitive_cells.v"
  ],
  "expected_outputs": [
    {
      "path": "submission/trojan_report.json",
      "description": "Single JSON object with top-level fields verdict, suspect_instances, justification, and (when verdict is trojan_detected) mismatching_inputs and cell_type_analysis."
    }
  ],
  "submission": {
    "path": "submission/trojan_report.json",
    "format": "json",
    "required_fields": ["verdict", "suspect_instances", "justification"],
    "conditional_fields": {
      "when": "verdict == trojan_detected",
      "fields": ["mismatching_inputs", "cell_type_analysis"]
    }
  },
  "toolchain": ["yosys", "iverilog", "vvp"],
  "evaluation": {
    "mode": "report_grading",
    "metrics": [
      {
        "name": "detection_rate",
        "description": "Fraction of graded submissions (across seeded netlist variants, if multiple are generated) that correctly report verdict=trojan_detected with the correct suspect instance identified.",
        "direction": "maximize"
      },
      {
        "name": "false_positive_rate",
        "description": "Fraction of submissions that report verdict=trojan_detected or list suspect_instances on a control/trojan-free netlist variant when one is included in the eval suite.",
        "direction": "minimize"
      },
      {
        "name": "localization_accuracy",
        "description": "Whether the exact ground-truth instance name and cell-type mismatch (found vs expected primitive) are correctly reported, independent of overall verdict correctness.",
        "direction": "maximize"
      },
      {
        "name": "inference_latency",
        "description": "Wall-clock time taken by evaluate.py to grade a single submission, including any optional iverilog/vvp cross-simulation of claimed mismatching inputs.",
        "direction": "minimize"
      }
    ]
  },
  "notes": "Participants must not modify anything under inputs/. Only yosys, iverilog, and vvp may be used for optional cross-checks; grading is based solely on the submitted JSON report."
}

`timescale 1ns/1ps

//
// primitive_cells.v
//
// Small behavioral standard-cell library used by inputs/netlist.v.
// Each cell is a pure combinational primitive with a fixed pinout:
//   - single-input cells expose ports .A, .Y
//   - two-input cells expose ports .A, .B, .Y
//
// These models are purely functional (behavioral) and are not meant to
// represent any particular physical library; they exist only so that
// inputs/netlist.v can be elaborated and simulated standalone with
// iverilog/vvp.
//

module BUF1 (
    input  A,
    output Y
);
    assign Y = A;
endmodule

module INV1 (
    input  A,
    output Y
);
    assign Y = ~A;
endmodule

module AND2 (
    input  A,
    input  B,
    output Y
);
    assign Y = A & B;
endmodule

module OR2 (
    input  A,
    input  B,
    output Y
);
    assign Y = A | B;
endmodule

module XOR2 (
    input  A,
    input  B,
    output Y
);
    assign Y = A ^ B;
endmodule

module XNOR2 (
    input  A,
    input  B,
    output Y
);
    assign Y = A ^ ~B;
endmodule

module NAND2 (
    input  A,
    input  B,
    output Y
);
    assign Y = ~(A & B);
endmodule

module NOR2 (
    input  A,
    input  B,
    output Y
);
    assign Y = ~(A | B);
endmodule

`timescale 1ns/1ps

//
// netlist.v
//
// Flattened, structural gate-level netlist for the perm_check
// permission comparator. Instantiates cells from
// inputs/primitive_cells.v (co-compile both files together, e.g.:
//   iverilog -g2012 inputs/primitive_cells.v inputs/netlist.v ...
// ).
//

module perm_check (
    input  [3:0] id_in,
    input  [3:0] id_auth,
    output       grant
);

    wire [3:0] eq;
    wire       lo_pair;
    wire       hi_pair;

    // Stage 1: per-bit equality
    XNOR2 u_eq0 (.A(id_in[0]), .B(id_auth[0]), .Y(eq[0]));
    XNOR2 u_eq1 (.A(id_in[1]), .B(id_auth[1]), .Y(eq[1]));
    XOR2  u_eq2 (.A(id_in[2]), .B(id_auth[2]), .Y(eq[2]));
    XNOR2 u_eq3 (.A(id_in[3]), .B(id_auth[3]), .Y(eq[3]));

    // Stage 2: AND-reduction tree
    AND2 u_and_lo    (.A(eq[0]), .B(eq[1]), .Y(lo_pair));
    AND2 u_and_hi    (.A(eq[2]), .B(eq[3]), .Y(hi_pair));
    AND2 u_and_final (.A(lo_pair), .B(hi_pair), .Y(grant));

endmodule

{
  "verdict": "trojan_free",
  "suspect_instances": [],
  "justification": "Netlist appears structurally consistent with a standard 4-bit equality comparator; no discrepancies observed during manual inspection."
}
